      END_STATE();
    case 5:
      if (lookahead == 'a') ADVANCE(23);
      END_STATE();
    case 6:
      if (lookahead == 'c') ADVANCE(11);
      END_STATE();
    case 7:
      if (lookahead == 'e') ADVANCE(22);
